// Shared vocabulary for the form, persisted briefs, and agent instructions.
export const methods={
  waterfall:{name:'Predictive · Waterfall',short:'Waterfall',icon:'git-branch',description:'Stable requirements. Sequential phases and approval gates.',protocol:'Baseline scope, schedule, and risks before Design. Work through Requirements, Design, Implementation, Testing, Deployment, and Maintenance in order. Keep requirement-to-test traceability. Route baseline changes to the sponsor with impact, options, and a recommendation. Continue unaffected work while waiting.'},
  scrum:{name:'Adaptive · Scrum',short:'Scrum',icon:'refresh-cw',description:'Evolving requirements. A backlog and fixed-capacity sprints.',protocol:'Keep an ordered Product Backlog and a Product Goal. Refine stories with testable acceptance criteria and estimates. Developers pull ready items into a fixed-capacity sprint with one Sprint Goal; do not extend the sprint. Facilitate planning, state-change syncs, a review of verified work, and a retrospective with one improvement. Unfinished work returns to the backlog, earns zero points, and never rolls over automatically.'},
  kanban:{name:'Adaptive · Kanban',short:'Kanban',icon:'columns-2',description:'Continuous work. Pull tasks while respecting WIP limits.',protocol:'Pull work when capacity is available. Finish and unblock downstream work before starting more. Blocked and review items still count against the work-in-progress limit. Keep entry and exit criteria explicit. Review aging work, cycle time, throughput, and one process improvement at each flow review.'},
  hybrid:{name:'Hybrid · Gates + sprints',short:'Hybrid',icon:'layers',description:'Fixed milestones outside. Scrum sprints inside delivery phases.',protocol:'Use Waterfall scope, schedule, risk baselines, and human-approved phase gates. Within Design, Implementation, and Testing use Scrum sprints: one goal, fixed capacity, independent verification, review, and retrospective. Keep each sprint inside its phase. Scope baseline changes go through sponsor change control.'}
};
export const phases=['Requirements','Design','Implementation','Testing','Deployment','Maintenance'];
export const defaultDoD='Acceptance criteria demonstrated with evidence; peer review by a different agent; relevant automated checks pass; security and integration checks completed; documentation updated; Product Owner or sponsor accepts the result. Record any task-specific exceptions before work starts.';
export const methodDefaults=(method='scrum')=>({method,goal:'',reason:'',definitionOfDone:defaultDoD,processLeadId:null,productOwnerId:null,qaLeadId:null,reviewerIds:[],sprintCapacity:13,syncCadence:'At meaningful state changes and each work cycle',wipLimit:3,scopeBaseline:'',scheduleBaseline:'',riskRegister:''});
export const hasPhases=m=>['waterfall','hybrid'].includes(m?.method);
export const hasSprints=m=>m?.method==='scrum'||m?.method==='hybrid';
export const sprintPhase=(m,flow)=>m?.method==='scrum'||m?.method==='hybrid'&&[1,2,3].includes(flow?.phaseIndex||0);
export const methodName=m=>methods[m?.method]?.name||'Existing workflow';
